        let (fa, _) = toks[c];
        let mut plen = 0usize;
        'pre: for p in 0..min_len {
            let v = input[fa as usize + p];
            for r in 1..nrows {
                let (a, _) = toks[r * ncols + c];
                if input[a as usize + p] != v {
