                }
            }
            plen += 1;
        }
        // Longest common suffix on the remainder.
        let mut slen = 0usize;
        'suf: for s in 0..(min_len - plen) {
            let (a0, b0) = toks[c];
            let v = input[b0 as usize - 1 - s];
            for r in 1..nrows {
                let (_, b) = toks[r * ncols + c];
                if input[b as usize - 1 - s] != v {
                    break 'suf;
                }
                let _ = a0;
            }
            slen += 1;
        }
        if plen == 0 && slen == 0 {
            let mut raw_c = Vec::with_capacity(raw_len);
            for r in 0..nrows {
                let (a, b) = toks[r * ncols + c];
                raw_c.extend_from_slice(&input[a as usize..b as usize]);
                raw_c.push(0);
            }
            segs.push(raw_c);
            continue;
        }
        let save = (plen.checked_add(slen)?).checked_mul(nrows)?;
        let overhead = varint_len(plen as u64)
            .checked_add(plen)?
            .checked_add(varint_len(slen as u64))?
            .checked_add(slen)?;
        // Raw-size gate: affix must save at least its header.
        if save <= overhead {
            let mut raw_c = Vec::with_capacity(raw_len);
            for r in 0..nrows {
                let (a, b) = toks[r * ncols + c];
                raw_c.extend_from_slice(&input[a as usize..b as usize]);
                raw_c.push(0);
            }
            segs.push(raw_c);
            continue;
        }
        let body_len = raw_len.checked_sub(save)?.checked_add(overhead)?;
        let mut d = Vec::with_capacity(body_len);
        put_varint(&mut d, plen as u64);
        d.extend_from_slice(&input[fa as usize..fa as usize + plen]);
        put_varint(&mut d, slen as u64);
        if slen > 0 {
            let (_, fb) = toks[c];
            d.extend_from_slice(&input[fb as usize - slen..fb as usize]);
        }
        for r in 0..nrows {
            let (a, b) = toks[r * ncols + c];
            let s = a as usize + plen;
            let e = b as usize - slen;
            if s > e {
                // Should not happen (bounded by min_len); fall back to raw.
                let mut raw_c = Vec::with_capacity(raw_len);
                for rr in 0..nrows {
                    let (aa, bb) = toks[rr * ncols + c];
                    raw_c.extend_from_slice(&input[aa as usize..bb as usize]);
                    raw_c.push(0);
                }
                segs.push(raw_c);
                // Undo mode bit if previously planned: not set yet, so clear.
                // Mark this column raw by swapping last push only.
                goto_next_column(&mut modes, &mut any_affix, c, false);
                // Need to remove the affix header already pushed: replace seg.
                // Simplest: keep raw seg just pushed and continue outer.
                // Since we already pushed raw, fix control flow via flag.
                // Use a sentinel: set a marker and break to next column.
                // We handle by continuing (segment already raw).
                break;
            }
            d.extend_from_slice(&input[s..e]);
            d.push(0);
        }
        // If the loop above hit the s>e guard it already pushed a raw seg
        // plus an extra partial affix seg; detect by length mismatch.
        // Rebuild correctly: if last seg is partial affix (no mode bit set
        // for this column) drop it.
        if segs.len() > c && (modes[c / 8] >> (c % 8)) & 1 == 0 && d.len() > overhead {
            // Check whether we pushed twice (guard path pushes raw into segs
            // and d holds a partial affix). The guard path pushed one raw seg
            // already, so discard the partial d.
            if segs.len() == c + 1 {
                continue;
            }
        }
        // Normal path: d holds the affix body.
        if segs.len() == c {
            modes[c / 8] |= 1u8 << (c % 8);
            segs.push(d);
            any_affix = true;
        }
    }
    if !any_affix {
        return None;
    }
    let mut t = meta.to_vec();
    t.extend_from_slice(&modes);
    for s in segs.iter() {
        t.extend_from_slice(s);
    }
    Some(t)
}

