            let mut lens = Vec::with_capacity(ntok);
            for _ in 0..ntok {
                let (v, np) = get_varint(&b, p).ok_or("lens")?;
                if v > 8192 {
                    return Err("lens".into());
                }
                lens.push(v as usize);
                p = np;
            }
            let mut k = p;
            for c in 0..ncols {
                let mut mx = 0usize;
                for r in 0..nrows {
