                for pl in 0..mx {
                    for r in 0..nrows {
                        let idx = r * ncols + c;
                        if pl < lens[idx] {
                            if k >= b.len() {
                                return Err("body".into());
                            }
                            col_tok[idx].push(b[k]);
                            k += 1;
                        }
                    }
                }
            }
