                            let (idv, n1) = get_varint(&b, k).ok_or("lens")?;
                            let (rlv, n2) = get_varint(&b, n1).ok_or("lens")?;
                            if idv >= nd as u64 {
                                return Err("lens".into());
                            }
                            let rl = (rlv as usize).checked_add(1).ok_or("lens")?;
                            if done.checked_add(rl).ok_or("lens")? > nrows {
                                return Err("lens".into());
